1	//! Bounded render-target allocation/test coordinator. It never requests a live
2	//! commit; the platform adapter is responsible for an atomic TEST_ONLY request.
3	use crate::output::{Assignment, Format, Plan};
4	use serde::Serialize;
5	
6	pub const MAX_TEST_TARGETS: usize = 32;
7	pub const MAX_TEST_PIXELS: u64 = 33_554_432;
8	pub const MAX_TEST_DIMENSION: u16 = 16_384;
9	pub const MAX_TEST_ATTEMPTS: usize = 64;
10	#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
11	pub enum TestStage {
12	    Inactive,
13	    UnsupportedLegacy,
14	    MissingPlan,
15	    NoTargets,
16	    Budget,
17	    StaleTopology,
18	    Properties,
19	    Allocate,
20	    AllocatedFormat,
21	    Export,
22	    Bind,
23	    Render,
24	    Sync,
25	    ModeBlob,
26	    AtomicTest,
27	    Cleanup,
28	}
29	#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
30	pub struct TestFailure {
31	    pub stage: TestStage,
32	    pub errno: Option<i32>,
33	}
34	impl TestFailure {
35	    pub fn at(stage: TestStage) -> Self {
36	        Self { stage, errno: None }
37	    }
38	}
39	#[derive(Clone, Debug, Serialize)]
40	pub struct TestedTarget {
41	    pub connector: u32,
42	    pub crtc: u32,
43	    pub primary_plane: u32,
44	    pub format: Format,
45	}
46	#[derive(Clone, Debug, Serialize)]
47	pub struct TestReport {
48	    pub ok: bool,
49	    pub planned_targets: usize,
50	    pub unassigned_connectors: usize,
51	    pub attempts: usize,
52	    /// Nominal width*height*4, not actual padded/compressed driver memory usage.
53	    pub nominal_bytes: String,
54	    pub tested_targets: Vec<TestedTarget>,
55	    pub failure: Option<TestFailure>,
56	    pub cleanup_failures: String,
57	}
58	/// Targets cannot escape run(); all successful and failed partial preparation
59	/// must retire before its report is returned. Platform allocations may block.
60	pub trait Backend {
61	    type Target;
62	    fn atomic(&self) -> bool;
63	    fn prepare(
64	        &mut self,
65	        assignment: &Assignment,
66	        format: Format,
67	    ) -> Result<Self::Target, TestFailure>;
68	    fn test_only(&mut self, targets: &[Self::Target]) -> Result<(), TestFailure>;
69	    fn cleanup_failures(&self) -> u64;
70	}
71	fn formats(assignment: &Assignment) -> Vec<Format> {
72	    // Known four-byte RGB render targets. Policy does not alias ARGB/XRGB or
73	    // implicit/Linear modifiers. Other formats need a separate render contract.
74	    const XRGB: u32 = u32::from_le_bytes(*b"XR24");
75	    const ARGB: u32 = u32::from_le_bytes(*b"AR24");
76	    let mut formats: Vec<_> = assignment
77	        .candidate_formats
78	        .iter()
79	        .copied()
80	        .filter(|f| f.code == XRGB || f.code == ARGB)
81	        .collect();
82	    formats.sort_by_key(|f| (f.code != XRGB, f.modifier));
83	    formats.dedup();
84	    formats
85	}
86	fn admission(plan: &Plan) -> Result<u64, TestFailure> {
87	    if plan.assignments.is_empty() {
88	        return Err(TestFailure::at(TestStage::NoTargets));
89	    }
90	    if plan.assignments.len() > MAX_TEST_TARGETS {
91	        return Err(TestFailure::at(TestStage::Budget));
92	    }
93	    let mut pixels = 0u64;
94	    let mut connectors = std::collections::BTreeSet::new();
95	    let mut encoders = std::collections::BTreeSet::new();
96	    let mut crtcs = std::collections::BTreeSet::new();
97	    let mut planes = std::collections::BTreeSet::new();
98	    for a in &plan.assignments {
99	        if a.mode.width == 0
100	            || a.mode.height == 0
101	            || a.mode.width > MAX_TEST_DIMENSION
102	            || a.mode.height > MAX_TEST_DIMENSION
103	            || a.mode.refresh_millihz().is_none()
104	            || a.connector == 0
105	            || a.encoder == 0
106	            || a.crtc == 0
107	            || a.primary_plane == 0
108	            || !connectors.insert(a.connector)
109	            || !encoders.insert(a.encoder)
110	            || !crtcs.insert(a.crtc)
111	            || !planes.insert(a.primary_plane)
112	            || a.candidate_formats.len() > crate::output::MAX_FORMATS
113	        {
114	            return Err(TestFailure::at(TestStage::Budget));
115	        }
116	        pixels = pixels
117	            .checked_add(u64::from(a.mode.width) * u64::from(a.mode.height))
118	            .ok_or_else(|| TestFailure::at(TestStage::Budget))?;
119	        if pixels > MAX_TEST_PIXELS {
120	            return Err(TestFailure::at(TestStage::Budget));
121	        }
122	    }
123	    Ok(pixels * 4)
124	}
125	pub fn run<B: Backend>(plan: &Plan, backend: &mut B) -> TestReport {
126	    let mut report = TestReport {
127	        ok: false,
128	        planned_targets: plan.assignments.len(),
129	        unassigned_connectors: plan.unassigned.len(),
130	        attempts: 0,
131	        nominal_bytes: "0".into(),
132	        tested_targets: vec![],
133	        failure: None,
134	        cleanup_failures: "0".into(),
135	    };
136	    let result = (|| {
137	        if !backend.atomic() {
138	            return Err(TestFailure::at(TestStage::UnsupportedLegacy));
139	        }
140	        report.nominal_bytes = admission(plan)?.to_string();
141	        let mut targets = vec![];
142	        for assignment in &plan.assignments {
143	            let mut prepared = None;
144	            let mut last = TestFailure::at(TestStage::AllocatedFormat);
145	            for format in formats(assignment) {
146	                if backend.cleanup_failures() > 0 {
147	                    return Err(TestFailure::at(TestStage::Cleanup));
148	                }
149	                if report.attempts == MAX_TEST_ATTEMPTS {
150	                    return Err(TestFailure::at(TestStage::Budget));
151	                }
152	                report.attempts += 1;
153	                match backend.prepare(assignment, format) {
154	                    Ok(target) => {
155	                        prepared = Some(target);
156	                        report.tested_targets.push(TestedTarget {
157	                            connector: assignment.connector,
158	                            crtc: assignment.crtc,
159	                            primary_plane: assignment.primary_plane,
160	                            format,
161	                        });
162	                        break;
163	                    }
164	                    Err(error)
165	                        if matches!(
166	                            error.stage,
167	                            TestStage::Allocate
168	                                | TestStage::AllocatedFormat
169	                                | TestStage::Export
170	                                | TestStage::Bind
171	                                | TestStage::Render
172	                        ) =>
173	                    {
174	                        last = error
175	                    }
176	                    Err(error) => return Err(error),
177	                }
178	            }
179	            targets.push(prepared.ok_or(last)?);
180	        }
181	        // Every target and mode/blob remains alive through the one joint test.
182	        backend.test_only(&targets)?;
183	        Ok(())
184	        // targets retire before checking cleanup accounting below, on all paths.
185	    })();
186	    report.failure = result.err();
187	    let failures = backend.cleanup_failures();
188	    report.cleanup_failures = failures.to_string();
189	    if failures > 0 && report.failure.is_none() {
190	        report.failure = Some(TestFailure::at(TestStage::Cleanup));
191	    }
192	    report.ok = report.failure.is_none();
193	    if !report.ok {
194	        report.tested_targets.clear();
195	    }
196	    report
197	}
