1	//! Manual atomic TEST_ONLY adapter. No DrmSurface or output manager is created:
2	//! their active teardown/legacy test paths can change real display state.
3	use crate::{
4	    output::{Assignment, Format, Plan},
5	    target::{self, Backend, TestFailure, TestReport, TestStage},
6	};
7	use smithay::{
8	    backend::{
9	        allocator::{
10	            Allocator, Buffer, Fourcc, Modifier,
11	            dmabuf::{AsDmabuf, Dmabuf},
12	            gbm::{GbmAllocator, GbmBuffer, GbmBufferFlags, GbmDevice},
13	        },
14	        drm::{DrmDevice, DrmDeviceFd},
15	        renderer::{Bind, Frame, Renderer, gles::GlesRenderer},
16	    },
17	    reexports::drm::control::{
18	        self, AtomicCommitFlags, Device as _, FbCmd2Flags, ResourceHandle, atomic::AtomicModeReq,
19	    },
20	    utils::{Rectangle, Transform},
21	};
22	use std::{
23	    cell::Cell,
24	    collections::{BTreeMap, BTreeSet},
25	    rc::Rc,
26	};
27	fn fail(stage: TestStage) -> TestFailure {
28	    TestFailure::at(stage)
29	}
30	fn io(stage: TestStage, error: std::io::Error) -> TestFailure {
31	    TestFailure {
32	        stage,
33	        errno: error.raw_os_error(),
34	    }
35	}
36	#[derive(Clone, Copy)]
37	enum Object {
38	    Framebuffer(control::framebuffer::Handle),
39	    Blob(u64),
40	}
41	struct Lease {
42	    fd: DrmDeviceFd,
43	    object: Object,
44	    failures: Rc<Cell<u64>>,
45	}
46	impl Drop for Lease {
47	    fn drop(&mut self) {
48	        let result = match self.object {
49	            Object::Framebuffer(fb) => self.fd.destroy_framebuffer(fb),
50	            Object::Blob(blob) => self.fd.destroy_property_blob(blob),
51	        };
52	        if result.is_err() {
53	            self.failures.set(self.failures.get().saturating_add(1));
54	        }
55	    }
56	}
57	struct Properties {
58	    object: control::RawResourceHandle,
59	    values: BTreeMap<String, (control::property::Handle, u64)>,
60	}
61	impl Properties {
62	    fn read<H: ResourceHandle>(drm: &DrmDevice, handle: H) -> Result<Self, TestFailure> {
63	        let values = drm
64	            .get_properties(handle)
65	            .map_err(|e| io(TestStage::Properties, e))?;
66	        if values.as_props_and_values().0.len() > 256 {
67	            return Err(fail(TestStage::Properties));
68	        }
69	        let mut map = BTreeMap::new();
70	        for (id, value) in values {
71	            let info = drm
72	                .get_property(id)
73	                .map_err(|e| io(TestStage::Properties, e))?;
74	            let name = info
75	                .name()
76	                .to_str()
77	                .map_err(|_| fail(TestStage::Properties))?
78	                .to_owned();
79	            if map.insert(name, (id, value)).is_some() {
80	                return Err(fail(TestStage::Properties));
81	            }
82	        }
83	        Ok(Self {
84	            object: handle.into(),
85	            values: map,
86	        })
87	    }
88	    fn set(&self, request: &mut AtomicModeReq, name: &str, value: u64) -> Result<(), TestFailure> {
89	        let (property, _) = self
90	            .values
91	            .get(name)
92	            .ok_or_else(|| fail(TestStage::Properties))?;
93	        request.add_raw_property(self.object, *property, value);
94	        Ok(())
95	    }
96	    fn optional(&self, request: &mut AtomicModeReq, name: &str, value: u64) {
97	        if let Some((property, _)) = self.values.get(name) {
98	            request.add_raw_property(self.object, *property, value);
99	        }
100	    }
101	}
102	struct Target {
103	    // Framebuffer and blob retire before DMA-BUF/GBM storage on every path.
104	    framebuffer: Lease,
105	    mode_blob: Lease,
106	    _dmabuf: Dmabuf,
107	    _buffer: GbmBuffer,
108	    assignment: Assignment,
109	    connector: Properties,
110	    crtc: Properties,
111	    plane: Properties,
112	}
113	struct Adapter<'a> {
114	    drm: &'a DrmDevice,
115	    renderer: &'a mut GlesRenderer,
116	    allocator: GbmAllocator<DrmDeviceFd>,
117	    modes: &'a BTreeMap<u32, Vec<control::Mode>>,
118	    failures: Rc<Cell<u64>>,
119	}
120	fn handle<H: ResourceHandle>(id: u32) -> Result<H, TestFailure> {
121	    control::from_u32(id).ok_or_else(|| fail(TestStage::StaleTopology))
122	}
123	/// Kept private, with no caller-supplied flags or live-commit entry point.
124	fn flags() -> AtomicCommitFlags {
125	    AtomicCommitFlags::TEST_ONLY | AtomicCommitFlags::ALLOW_MODESET
126	}
127	impl Backend for Adapter<'_> {
128	    type Target = Target;
129	    fn atomic(&self) -> bool {
130	        self.drm.is_atomic()
131	    }
132	    fn cleanup_failures(&self) -> u64 {
133	        self.failures.get()
134	    }
135	    fn prepare(&mut self, a: &Assignment, format: Format) -> Result<Target, TestFailure> {
136	        if !self.drm.is_active() {
137	            return Err(fail(TestStage::Inactive));
138	        }
139	        let connector = handle::<control::connector::Handle>(a.connector)?;
140	        let encoder = handle::<control::encoder::Handle>(a.encoder)?;
141	        let crtc = handle::<control::crtc::Handle>(a.crtc)?;
142	        let plane = handle::<control::plane::Handle>(a.primary_plane)?;
143	        let mode = *self
144	            .modes
145	            .get(&a.connector)
146	            .and_then(|m| m.get(a.mode_index))
147	            .ok_or_else(|| fail(TestStage::StaleTopology))?;
148	        let live = self
149	            .drm
150	            .get_connector(connector, false)
151	            .map_err(|e| io(TestStage::StaleTopology, e))?;
152	        if live.state() != control::connector::State::Connected
153	            || !live.modes().contains(&mode)
154	            || !live.encoders().contains(&encoder)
155	        {
156	            return Err(fail(TestStage::StaleTopology));
157	        }
158	        let resources = self
159	            .drm
160	            .resource_handles()
161	            .map_err(|e| io(TestStage::StaleTopology, e))?;
162	        if resources.crtcs().len() > crate::output::MAX_CRTCS {
163	            return Err(fail(TestStage::StaleTopology));
164	        }
165	        let encoder_info = self
166	            .drm
167	            .get_encoder(encoder)
168	            .map_err(|e| io(TestStage::StaleTopology, e))?;
169	        if !resources
170	            .filter_crtcs(encoder_info.possible_crtcs())
171	            .contains(&crtc)
172	        {
173	            return Err(fail(TestStage::StaleTopology));
174	        }
175	        let native_format = smithay::backend::allocator::Format {
176	            code: Fourcc::try_from(format.code).map_err(|_| fail(TestStage::AllocatedFormat))?,
177	            modifier: Modifier::from(format.modifier),
178	        };
179	        let primary = self
180	            .drm
181	            .planes(&crtc)
182	            .map_err(|_| fail(TestStage::StaleTopology))?
183	            .primary;
184	        if !primary
185	            .iter()
186	            .any(|p| p.handle == plane && p.formats.contains(&native_format))
187	        {
188	            return Err(fail(TestStage::StaleTopology));
189	        }
190	        let connector_properties = Properties::read(self.drm, connector)?;
191	        if connector_properties
192	            .values
193	            .get("non-desktop")
194	            .is_some_and(|(_, value)| *value != 0)
195	        {
196	            return Err(fail(TestStage::StaleTopology));
197	        }
198	        let crtc_properties = Properties::read(self.drm, crtc)?;
199	        let plane_properties = Properties::read(self.drm, plane)?;
200	        let buffer = self
201	            .allocator
202	            .create_buffer(
203	                u32::from(a.mode.width),
204	                u32::from(a.mode.height),
205	                native_format.code,
206	                &[native_format.modifier],
207	            )
208	            .map_err(|e| io(TestStage::Allocate, e))?;
209	        // GBM may fall back from an explicit modifier to implicit allocation.
210	        // Such a buffer must never be tested under the requested explicit pair.
211	        if buffer.format() != native_format
212	            || buffer.width() != u32::from(a.mode.width)
213	            || buffer.height() != u32::from(a.mode.height)
214	        {
215	            return Err(fail(TestStage::AllocatedFormat));
216	        }
217	        let fb_flags = if native_format.modifier == Modifier::Invalid {
218	            FbCmd2Flags::empty()
219	        } else {
220	            FbCmd2Flags::MODIFIERS
221	        };
222	        let framebuffer = self
223	            .drm
224	            .add_planar_framebuffer(&buffer, fb_flags)
225	            .map_err(|e| io(TestStage::Export, e))?;
226	        let framebuffer = Lease {
227	            fd: self.drm.device_fd().clone(),
228	            object: Object::Framebuffer(framebuffer),
229	            failures: self.failures.clone(),
230	        };
231	        let mut dmabuf = buffer.export().map_err(|_| fail(TestStage::Export))?;
232	        let sync = {
233	            let mut target = self
234	                .renderer
235	                .bind(&mut dmabuf)
236	                .map_err(|_| fail(TestStage::Bind))?;
237	            let size = (i32::from(a.mode.width), i32::from(a.mode.height)).into();
238	            let mut frame = self
239	                .renderer
240	                .render(&mut target, size, Transform::Normal)
241	                .map_err(|_| fail(TestStage::Render))?;
242	            frame
243	                .clear([0., 0., 0., 1.].into(), &[Rectangle::from_size(size)])
244	                .map_err(|_| fail(TestStage::Render))?;
245	            frame.finish().map_err(|_| fail(TestStage::Render))?
246	        };
247	        let mut reached = false;
248	        for _ in 0..8 {
249	            if sync.wait().is_ok() {
250	                reached = true;
251	                break;
252	            }
253	        }
254	        if !reached {
255	            return Err(fail(TestStage::Sync));
256	        }
257	        let blob = self
258	            .drm
259	            .create_property_blob(&mode)
260	            .map_err(|e| io(TestStage::ModeBlob, e))?
261	            .as_blob()
262	            .ok_or_else(|| fail(TestStage::ModeBlob))?;
263	        let mode_blob = Lease {
264	            fd: self.drm.device_fd().clone(),
265	            object: Object::Blob(blob),
266	            failures: self.failures.clone(),
267	        };
268	        Ok(Target {
269	            framebuffer,
270	            mode_blob,
271	            _dmabuf: dmabuf,
272	            _buffer: buffer,
273	            assignment: a.clone(),
274	            connector: connector_properties,
275	            crtc: crtc_properties,
276	            plane: plane_properties,
277	        })
278	    }
279	    fn test_only(&mut self, targets: &[Target]) -> Result<(), TestFailure> {
280	        if !self.drm.is_active() || !self.drm.is_atomic() {
281	            return Err(fail(TestStage::Inactive));
282	        }
283	        let mut request = AtomicModeReq::new();
284	        let crtcs: BTreeSet<_> = targets.iter().map(|t| t.assignment.crtc).collect();
285	        let primary: BTreeSet<_> = targets.iter().map(|t| t.assignment.primary_plane).collect();
286	        for target in targets {
287	            let a = &target.assignment;
288	            let Object::Framebuffer(fb) = target.framebuffer.object else {
289	                unreachable!()
290	            };
291	            let Object::Blob(blob) = target.mode_blob.object else {
292	                unreachable!()
293	            };
294	            target
295	                .connector
296	                .set(&mut request, "CRTC_ID", u64::from(a.crtc))?;
297	            target.crtc.set(&mut request, "ACTIVE", 1)?;
298	            target.crtc.set(&mut request, "MODE_ID", blob)?;
299	            for (name, value) in [
300	                ("FB_ID", u64::from(u32::from(fb))),
301	                ("CRTC_ID", u64::from(a.crtc)),
302	                ("SRC_X", 0),
303	                ("SRC_Y", 0),
304	                ("SRC_W", u64::from(a.mode.width) << 16),
305	                ("SRC_H", u64::from(a.mode.height) << 16),
306	                ("CRTC_X", 0),
307	                ("CRTC_Y", 0),
308	                ("CRTC_W", u64::from(a.mode.width)),
309	                ("CRTC_H", u64::from(a.mode.height)),
310	            ] {
311	                target.plane.set(&mut request, name, value)?;
312	            }
313	            target.plane.optional(&mut request, "rotation", 1);
314	            target.plane.optional(&mut request, "alpha", 65535);
315	        }
316	        // Remove overlay/cursor state on the tested CRTCs from this hypothetical
317	        // request. No live change is made, and unrelated CRTCs are untouched.
318	        let planes = self
319	            .drm
320	            .plane_handles()
321	            .map_err(|e| io(TestStage::Properties, e))?;
322	        if planes.len() > 256 {
323	            return Err(fail(TestStage::Budget));
324	        }
325	        for plane in planes {
326	            let info = self
327	                .drm
328	                .get_plane(plane)
329	                .map_err(|e| io(TestStage::Properties, e))?;
330	            if !primary.contains(&u32::from(plane))
331	                && info
332	                    .crtc()
333	                    .is_some_and(|crtc| crtcs.contains(&u32::from(crtc)))
334	            {
335	                let properties = Properties::read(self.drm, plane)?;
336	                properties.set(&mut request, "FB_ID", 0)?;
337	                properties.set(&mut request, "CRTC_ID", 0)?;
338	            }
339	        }
340	        self.drm
341	            .atomic_commit(flags(), request)
342	            .map_err(|e| io(TestStage::AtomicTest, e))
343	    }
344	}
345	pub(super) fn test(
346	    drm: &DrmDevice,
347	    gbm: &GbmDevice<DrmDeviceFd>,
348	    renderer: &mut GlesRenderer,
349	    modes: &BTreeMap<u32, Vec<control::Mode>>,
350	    plan: &Plan,
351	) -> TestReport {
352	    let mut adapter = Adapter {
353	        drm,
354	        renderer,
